"use strict";(self.webpackChunkvault_assistant_docs=self.webpackChunkvault_assistant_docs||[]).push([["5265"],{4803(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"docsSidebar":[{"type":"link","href":"/vault-assistant/docs/","label":"Home","docId":"intro","unlisted":false},{"type":"category","label":"Getting Started","items":[{"type":"link","href":"/vault-assistant/docs/getting-started/introduction","label":"Introduction","docId":"getting-started/introduction","unlisted":false},{"type":"link","href":"/vault-assistant/docs/getting-started/installation","label":"Installation","docId":"getting-started/installation","unlisted":false},{"type":"link","href":"/vault-assistant/docs/getting-started/prerequisites","label":"System prerequisites","docId":"getting-started/prerequisites","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Interfaces","items":[{"type":"link","href":"/vault-assistant/docs/interfaces/web-app","label":"Web interface","docId":"interfaces/web-app","unlisted":false},{"type":"link","href":"/vault-assistant/docs/interfaces/desktop-app","label":"Desktop app (Tauri)","docId":"interfaces/desktop-app","unlisted":false},{"type":"link","href":"/vault-assistant/docs/interfaces/tui","label":"Terminal interface (TUI)","docId":"interfaces/tui","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Features","items":[{"type":"link","href":"/vault-assistant/docs/features/ask-mode","label":"Ask mode","docId":"features/ask-mode","unlisted":false},{"type":"link","href":"/vault-assistant/docs/features/draft-mode","label":"Draft mode","docId":"features/draft-mode","unlisted":false},{"type":"link","href":"/vault-assistant/docs/features/write-vault","label":"Write to vault features","docId":"features/write-vault","unlisted":false},{"type":"link","href":"/vault-assistant/docs/features/rag","label":"Retrieval-Augmented Generation (RAG)","docId":"features/rag","unlisted":false},{"type":"link","href":"/vault-assistant/docs/features/web-research","label":"Local web research","docId":"features/web-research","unlisted":false},{"type":"link","href":"/vault-assistant/docs/features/settings","label":"Settings panel features","docId":"features/settings","unlisted":false},{"type":"link","href":"/vault-assistant/docs/features/skills","label":"Custom skills","docId":"features/skills","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Architecture","items":[{"type":"link","href":"/vault-assistant/docs/architecture/overview","label":"Architecture overview","docId":"architecture/overview","unlisted":false},{"type":"link","href":"/vault-assistant/docs/architecture/design-system","label":"Design system and interface styling","docId":"architecture/design-system","unlisted":false},{"type":"link","href":"/vault-assistant/docs/architecture/development-workflow","label":"Developer workflow and guidelines","docId":"architecture/development-workflow","unlisted":false},{"type":"link","href":"/vault-assistant/docs/architecture/workflow","label":"Quick Rules","docId":"architecture/workflow","unlisted":false}],"collapsed":true,"collapsible":true}]},"docs":{"architecture/design-system":{"id":"architecture/design-system","title":"Design system and interface styling","description":"The Vault Assistant interface uses a clean, developer-focused aesthetic: dark surfaces, monospaced labels, status badges, and segmented chips.","sidebar":"docsSidebar"},"architecture/development-workflow":{"id":"architecture/development-workflow","title":"Developer workflow and guidelines","description":"This page outlines the development process, testing requirements, and coding conventions for adding features or modifying the Vault Assistant codebase.","sidebar":"docsSidebar"},"architecture/overview":{"id":"architecture/overview","title":"Architecture overview","description":"This document details the Vault Assistant process model, request lifecycle, and engine execution structure.","sidebar":"docsSidebar"},"architecture/workflow":{"id":"architecture/workflow","title":"Developer Workflow (Quick Rules)","description":"This file outlines the core rules for developing Vault Assistant. The full developer guide lives in the nested documentation folder at development-workflow.md.","sidebar":"docsSidebar"},"features/ask-mode":{"id":"features/ask-mode","title":"Ask mode","description":"Ask mode is the default mode for new tabs. You type a question, the model reads context from your vault files, and the answer streams back into the tab. This page also documents the controls shared with Draft mode: the generation toggles and the answer area work the same way in both.","sidebar":"docsSidebar"},"features/draft-mode":{"id":"features/draft-mode","title":"Draft mode","description":"Draft mode (called job mode internally) writes structured, first-person text grounded in your vault, aimed at job applications and similar prompts where the answer speaks as you. You paste the target context, ask the question, and the model drafts a response in your voice using only facts it can find in your notes.","sidebar":"docsSidebar"},"features/rag":{"id":"features/rag","title":"Retrieval-Augmented Generation (RAG)","description":"Retrieval-Augmented Generation (RAG) sends only the relevant slices of your vault to the model for each query. This limits token usage while keeping answers grounded in your notes.","sidebar":"docsSidebar"},"features/settings":{"id":"features/settings","title":"Settings panel features","description":"The settings panel allows you to customize default models, vault directories, persona prompts, visual themes, and custom skills. Clicking the gear icon (\u2699) in the top right header opens the drawer.","sidebar":"docsSidebar"},"features/skills":{"id":"features/skills","title":"Custom skills","description":"Vault Assistant supports portable skill files to guide model behavior. These files follow the Claude Skill format. The application extracts the instructions and injects them into the prompts for both Claude Code and all supported CLI engines.","sidebar":"docsSidebar"},"features/web-research":{"id":"features/web-research","title":"Local web research","description":"Vault Assistant can grant Claude Code and local CLI engines search and page-reading capabilities without requiring paid APIs. This feature is disabled by default.","sidebar":"docsSidebar"},"features/write-vault":{"id":"features/write-vault","title":"Write to vault features","description":"The Write to vault mode lets you add, modify, or format files inside your local vault. Rather than letting the model write files directly, the application uses a secure approval pipeline. Nothing is saved to disk until you review the changes and approve them.","sidebar":"docsSidebar"},"getting-started/installation":{"id":"getting-started/installation","title":"Installation","description":"You can install Vault Assistant three ways: from npm, as a packaged desktop app, or straight from the source tree. All of them run on macOS and Linux. There is no Windows build yet.","sidebar":"docsSidebar"},"getting-started/introduction":{"id":"getting-started/introduction","title":"Introduction","description":"Vault Assistant is a local application that drafts grounded, natural text based on files in your Obsidian vault. A single Bun process serves a React web interface and a terminal interface (TUI), and an optional desktop app wraps the web interface in a native window.","sidebar":"docsSidebar"},"getting-started/prerequisites":{"id":"getting-started/prerequisites","title":"System prerequisites","description":"This page lists the system dependencies required to install, build, and run the Vault Assistant. For the install commands themselves, start at Installation.","sidebar":"docsSidebar"},"interfaces/desktop-app":{"id":"interfaces/desktop-app","title":"Desktop app (Tauri)","description":"The desktop app is the web interface in a native window. It exists for people who want a dock icon and a standalone window instead of a browser tab. Feature-wise the two are identical.","sidebar":"docsSidebar"},"interfaces/tui":{"id":"interfaces/tui","title":"Terminal interface (TUI)","description":"The TUI is a full terminal client built with React and Ink. It talks to the same server and API as the web interface, so answers, settings, and sessions are shared. If a server is already running it connects to it; otherwise it starts one itself and shuts it down when you quit.","sidebar":"docsSidebar"},"interfaces/web-app":{"id":"interfaces/web-app","title":"Web interface","description":"The web interface is the default frontend. Starting the app in any form serves it//localhost:5173 unless you changed the port, and the desktop app wraps this same interface in its own window.","sidebar":"docsSidebar"},"intro":{"id":"intro","title":"Vault Assistant Documentation","description":"Welcome to the Vault Assistant documentation. This guide details how the application works, how to configure its features, and how to contribute to its development.","sidebar":"docsSidebar"}}}}')}}]);